func TestScratchMigrateAndSearch(t *testing.T) {
	f := newFakeDynamo()
	l := newTestLog(t, f)

	// Insert two events WITHOUT CreatedAtDate, on either side of a month boundary.
	addLegacy := func(sid string, index int, ts time.Time) {
		f.items[l.Tablename][fmt.Sprintf("%v|%v", sid, index)] = map[string]favtr{
			keySessionID:     {S: sid},
			keyEventIndex:    {N: strconv.Itoa(index)},
			keyEventType:     {S: events.UserLocalLogin},
			keyCreatedAt:     {N: strconv.FormatInt(ts.Unix(), 10)},
			keyEventNamespace: {S: "default"},
			"Fields":           {S: fmt.Sprintf(`{"%v":"%v","%v":"%v"}`, events.EventType, events.UserLocalLogin, events.EventUser, "bob")},
		}
	}
	addLegacy("s1", 1, time.Date(2019, 1, 31, 22, 0, 0, 0, time.UTC))
	addLegacy("s2", 2, time.Date(2019, 2, 1, 2, 0, 0, 0, time.UTC))

	if _, ok := f.items[l.Tablename]["s1|1"][keyDate]; ok {
		t.Fatal("precondition: item should not have CreatedAtDate")
	}

	if err := l.migrateDateAttribute(context.Background()); err != nil {
		t.Fatal(err)
	}
	if got := f.items[l.Tablename]["s1|1"][keyDate].S; got != "2019-01-31" {
		t.Fatalf("migration did not set CreatedAtDate: %q", got)
	}
	if got := f.items[l.Tablename]["s2|1+1"]; got.S != "" {
		_ = got
	}
	if got := f.items[l.Tablename]["s2|2"][keyDate].S; got != "2019-02-01" {
		t.Fatalf("migration did not set CreatedAtDate: %q", got)
	}

	// Search across the month boundary must return both events.
	fields, err := l.SearchEvents(
		time.Date(2019, 1, 31, 0, 0, 0, 0, time.UTC),
		time.Date(2019, 2, 1, 23, 59, 59, 0, time.UTC),
		"", 0)
	if err != nil {
		t.Fatal(err)
	}
	if len(fields) != 2 {
		t.Fatalf("expected 2 events, got %v (%v)", len(fields), fields)
	}

	// canceled context must be honored
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if err := l.migrateDateAttribute(ctx); err == nil {
		t.Fatal("expected error from canceled context")
	}
}

